import{asTrimmedNonEmptyString as asString}from"../utils/text.js";import{RoomType}from"./proto/generated/index.js";export const getImChatMessageEventMetadata=e=>{if("chatMessage"!==e.payload?.case)return;const a=asString(e.payload.value.chatId),t=asString(e.payload.value.messageId);if(!t)return;const o=asString(e.id),r=asString(e.payload.value.senderId),d=asString(e.payload.value.senderShortId),s=!0===e.payload.value.mentioned,n=asString(e.payload.value.roomType===RoomType.GROUP?e.payload.value.roomId:"");return{...o?{eventId:o}:{},...a?{chatId:a}:{},messageId:t,...r?{senderId:r}:{},...d?{senderShortId:d}:{},...s?{mentioned:s}:{},...n?{roomId:n}:{}}};